关闭附加分量场，以较小文件保留整体动量信息。
functions
{
momentum
{
type momentum;
libs (fieldFunctionObjects);
log true;
useNamePrefix true;
executeInterval 10;
writeControl writeTime;
writeMomentum false;
writePosition false;
writeVelocity false;
regionType all;
cylindrical true;
origin (0 0 0);
rotation
{
type cylindrical;
axis (1 0 0);
}
}
}
